# Generated by OrchestKit Claude Plugin
# Created: 2026-07-31

"""What a sweep leaves behind: a report, and drafts nobody files automatically (plan T2.8).

Stage 2 may not open issues on its own (decision e) — the repo is public, the model is an
unreliable narrator, and an issue is visible forever. So this produces a `summary.md` and, for
each finding that survived K-of-N, a **draft**. Filing is the user's move.

The header carries three sentences that are easy to omit and expensive to omit, because a report
that does not say them will be read as claiming more than it proves:

* **tier 3 is advisory** — a read use case never fails a run;
* **"all 31 tools covered" is not "all 31 tools gated"** — the coverage map's own grades say how
  many slots can actually fail if the wrong tool was used;
* **what it cost**, cumulatively, out of the same window the user works in.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence

from stage2.coverage import COVERAGE, gating
from stage2.gates import Verdict, dedup_key
from stage2.sweep import Graded

TITLE = "# Stage 2 — real-model sweep"


def summary(
    verdicts: Sequence[Verdict],
    graded: Sequence[Graded],
    *,
    spent: float,
    budget: float | None = None,
    stamp: str = "",
) -> str:
    """The whole report, as markdown."""
    lines = [TITLE, ""]
    if stamp:
        lines += [f"Run: {stamp}", ""]
    lines += _header(spent, budget) + [""] + _table(verdicts) + [""]
    lines += _findings(verdicts, graded)
    return "\n".join(lines) + "\n"


def drafts(verdicts: Sequence[Verdict], graded: Sequence[Graded]) -> list[tuple[str, str]]:
    """One `(title, body)` per reportable finding. Nothing is filed here."""
    return [
        (_title(verdict, assertion), _body(verdict, assertion, graded))
        for verdict in verdicts
        if verdict.reportable
        for assertion in verdict.recurring
    ]


def _header(spent: float, budget: float | None) -> list[str]:
    grades = [slot.grade for slot in COVERAGE.values()]
    gated = sum(1 for grade in grades if gating(grade))
    allowance = f" of ${budget:.2f} allowed" if budget is not None else ""
    return [
        "## How to read this",
        "",
        f"* **Cost: ${spent:.4f}{allowance}**, from the same subscription window you work in.",
        f"* **Coverage is not gating.** All {len(COVERAGE)} tools have a use case; "
        f"{gated} of them have one whose failure can be attributed to *that* tool. "
        f"The other {len(COVERAGE) - gated} are substitutable reads and behavioural twins — "
        "covered, never gated.",
        "* **Tier 3 is advisory.** A read-only use case reports and never fails the sweep.",
        "* **Nothing here was filed.** Drafts are drafts; opening an issue is your call.",
    ]


def _table(verdicts: Sequence[Verdict]) -> list[str]:
    rows = [
        "## Use cases",
        "",
        "| use case | attempts | failed | inconclusive | cost | verdict |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for verdict in verdicts:
        rows.append(
            f"| {verdict.use_case} | {len(verdict.attempts)} | {verdict.failures} | "
            f"{verdict.inconclusive} | ${verdict.cost_usd:.4f} | {_verdict_word(verdict)} |"
        )
    return rows


def _verdict_word(verdict: Verdict) -> str:
    if verdict.reportable:
        return "**finding**"
    if verdict.watch:
        return "watch"
    if verdict.failures:
        return "flake (1 of N)"
    if verdict.passes:
        return "pass"
    return "inconclusive"


def _findings(verdicts: Sequence[Verdict], graded: Sequence[Graded]) -> list[str]:
    reportable = [verdict for verdict in verdicts if verdict.reportable]
    watched = [verdict for verdict in verdicts if verdict.watch]
    lines = ["## Findings", ""]
    if not reportable:
        lines += ["Nothing reached K of N.", ""]
    for verdict in reportable:
        for assertion in verdict.recurring:
            lines += [
                f"### {assertion}",
                "",
                f"Failed in {verdict.failures} of {len(verdict.attempts)} attempts.",
                "",
                *_details(assertion, graded),
                "",
            ]
    if watched:
        lines += [
            "## Watch",
            "",
            "Seen twice, not three times — reported here and deliberately not drafted:",
            "",
            *[
                f"* {verdict.use_case}: {verdict.failures} of {len(verdict.attempts)}"
                for verdict in watched
            ],
            "",
        ]
    return lines


def _details(assertion: str, graded: Sequence[Graded]) -> list[str]:
    seen = [
        f"* `{outcome.detail}`"
        for entry in graded
        for outcome in entry.failures
        if outcome.id == assertion
    ]
    return sorted(set(seen)) or ["* (no detail recorded)"]


def _title(verdict: Verdict, assertion: str) -> str:
    return f"Stage 2: {assertion} fails {verdict.failures}/{len(verdict.attempts)} runs"


def _body(verdict: Verdict, assertion: str, graded: Sequence[Graded]) -> str:
    prompts = sorted({entry.run.use_case for entry in graded if entry.use_case == verdict.use_case})
    return "\n".join(
        [
            f"{dedup_key(verdict.use_case, assertion)}",
            "",
            f"A real model, given only the tool docstrings, failed `{assertion}` in "
            f"**{verdict.failures} of {len(verdict.attempts)}** independent runs "
            f"({verdict.use_case}).",
            "",
            "What the tree said afterwards:",
            "",
            *_details(assertion, graded),
            "",
            "This is a class-A assertion: it is read back over REST after the call, so it is a "
            "statement about the tree and not about the model's account of it.",
            "",
            f"Use cases involved: {', '.join(prompts) or verdict.use_case}.",
        ]
    )


def window_note(usage: Mapping[str, object]) -> str:
    """The `usage` block of the last `result` event, verbatim — tokens, not dollars."""
    return ", ".join(f"{key}={value}" for key, value in sorted(usage.items()))
